class MyQueue {
private:
    stack<int> inStk;    // 專門負責 push
    stack<int> outStk;   // 專門負責 pop / peek

    // 關鍵：只有 out 空的時候才搬運
    void transfer() {
        if (outStk.empty()) {
            while (!inStk.empty()) {
                outStk.push(inStk.top());
                inStk.pop();
            }
        }
    }

public:
    MyQueue() {}

    void push(int x) {
        inStk.push(x);
    }

    int pop() {
        transfer();
        int val = outStk.top();
        outStk.pop();
        return val;
    }

    int peek() {
        transfer();
        return outStk.top();
    }

    bool empty() {
        return inStk.empty() && outStk.empty();
    }
};

